// Prijscontrole: rekent de prijsindicatie uit met de prijzen uit de Sheet Tarieven.
// De aanvraag van de site levert alleen id's en aantallen; prijzen uit de aanvraag worden nooit gebruikt.

const body = $('Beveiliging').first().json.body || {};
const rijen = $input.all().map(i => i.json);

// Tarieven per id, uit de Sheet
const tarief = {};
for (const r of rijen) {
  tarief[String(r.id).trim()] = r;
}

// Welke posten bij welk pad horen (zelfde regels als offerte.html)
const TOEGELATEN = {
  website:       ['basiswebsite', 'extra_pagina', 'onderhoud_website', 'seo_geo', 'ai_contactformulier', 'automatisering', 'onderhoud_ai'],
  automatisatie: ['ai_contactformulier', 'automatisering', 'onderhoud_ai'],
  google:        ['seo_geo']
};
const AI_POSTEN = ['ai_contactformulier', 'automatisering'];
const MAX_PAGINAS = 20;

const pad = String(body.pad || '').trim();
const padGeldig = Object.prototype.hasOwnProperty.call(TOEGELATEN, pad);
const keuzes = Array.isArray(body.keuzes) ? body.keuzes : [];

const gekozen = {};   // id -> aantal
const geweigerd = [];

for (const k of keuzes) {
  const id = String((k && k.id) || '').trim();
  if (!padGeldig || !tarief[id] || !TOEGELATEN[pad].includes(id) || gekozen[id]) {
    geweigerd.push(id || '(leeg)');
    continue;
  }
  let aantal = 1;
  if (id === 'extra_pagina') {
    aantal = Math.floor(Number(k.aantal));
    if (!(aantal >= 1)) aantal = 1;
    if (aantal > MAX_PAGINAS) aantal = MAX_PAGINAS;
  }
  gekozen[id] = aantal;
}

// Verplichte regel: onderhoud AI hoort bij elke AI-intake of automatisering, en nergens anders
const heeftAI = AI_POSTEN.some(id => gekozen[id]);
if (heeftAI && !gekozen.onderhoud_ai && tarief.onderhoud_ai) {
  gekozen.onderhoud_ai = 1;
}
if (!heeftAI && gekozen.onderhoud_ai) {
  delete gekozen.onderhoud_ai;
  geweigerd.push('onderhoud_ai');
}

// Posten opbouwen in de volgorde van de Sheet
const posten = rijen
  .filter(r => gekozen[String(r.id).trim()])
  .sort((a, b) => a.row_number - b.row_number)
  .map(r => {
    const id = String(r.id).trim();
    const prijs = Number(r.prijs);
    const aantal = gekozen[id];
    return {
      id: id,
      post: r.post,
      dienst: r.dienst,
      betaling: r.betaling,
      prijs: prijs,
      aantal: aantal,
      bedrag: prijs * aantal,
      vanaf: String(r.vanaf).trim().toLowerCase() === 'ja'
    };
  });

let totaalEenmalig = 0, totaalMaandelijks = 0, vanafEenmalig = false, vanafMaandelijks = false;
for (const p of posten) {
  if (p.betaling === 'maandelijks') {
    totaalMaandelijks += p.bedrag;
    vanafMaandelijks = vanafMaandelijks || p.vanaf;
  } else {
    totaalEenmalig += p.bedrag;
    vanafEenmalig = vanafEenmalig || p.vanaf;
  }
}

return [{
  json: {
    pad: padGeldig ? pad : 'ongeldig',
    naam: String(body.naam || '').trim(),
    email: String(body.email || '').trim(),
    bedrijf: String(body.bedrijf || '').trim(),
    telefoon: String(body.telefoon || '').trim(),
    opmerking: String(body.opmerking || '').trim(),
    omschrijving_automatisering: String(body.omschrijving_automatisering || '').trim(),
    posten: posten,
    totaalEenmalig: totaalEenmalig,
    vanafEenmalig: vanafEenmalig,
    totaalMaandelijks: totaalMaandelijks,
    vanafMaandelijks: vanafMaandelijks,
    geweigerd: geweigerd
  }
}];

