// Offerte samenstellen: AI-tekst + berekening uit Prijscontrole = mail met prijsindicatie (HTML + tekst).
// Bedragen, vaste zinnen, afsluiter en opmaak komen uit deze code, nooit uit de AI.

const pc = $('Prijscontrole').first().json;
const ruw = String($input.first().json.output || '');
const waarschuwingen = [].concat($('Beveiliging').first().json.beveiligingWaarschuwingen || []);
const LOGO = 'https://weblotus.be/preview-x7k2/logo-mail.png';

// Tekst veilig maken voor HTML
function esc(t) {
  return String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// AI-antwoord lezen (```json-randjes eerst wegknippen)
let onderdelen = [];
let samenvatting = '';
let antwoordOpmerking = '';
let ruweAI = '';
const schoon = ruw.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
try {
  const p = JSON.parse(schoon);
  samenvatting = String(p.samenvatting || '').trim();
  antwoordOpmerking = pc.opmerking ? String(p.antwoordOpmerking || '').trim() : '';
  onderdelen = (Array.isArray(p.onderdelen) ? p.onderdelen : []).map(o => ({
    onderdeel: String(o.onderdeel || '').trim(),
    zin: String(o.zin || '').trim(),
    vraag: String(o.vraag || '').trim()
  })).filter(o => o.onderdeel || o.zin);
} catch (e) {
  ruweAI = ruw.trim();
  waarschuwingen.push('De AI-tekst kon niet gelezen worden als JSON; de ruwe tekst staat in de mail. Nakijken!');
}

// Verdediging: groet en bedragen in de AI-tekst
const aiTekst = onderdelen.map(o => o.zin + ' ' + o.vraag).join(' ') + ' ' + antwoordOpmerking + ' ' + ruweAI;
if (/met vriendelijke groet/i.test(aiTekst)) {
  waarschuwingen.push('De AI schreef een groet in de tekst. Nakijken!');
}
if (/€|euro/i.test(aiTekst)) {
  waarschuwingen.push('De AI noemt een bedrag in de tekst. Nakijken voor verzending!');
}

// Bedragen opmaken zoals in België: € 2.640
function euro(n) {
  return '€ ' + Math.round(Number(n)).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

// Prijsregels
const regels = pc.posten.map(p => ({
  naam: p.aantal > 1 ? p.post + ' × ' + p.aantal : p.post,
  bedrag: (p.vanaf ? 'vanaf ' : '') + euro(p.bedrag) + (p.betaling === 'maandelijks' ? ' per maand' : '')
}));

// Totalen: eenmalig samen, maandkosten per soort apart
const totalen = [];
if (pc.totaalEenmalig > 0) {
  totalen.push({ label: 'Eenmalige kost', bedrag: (pc.vanafEenmalig ? 'vanaf ' : '') + euro(pc.totaalEenmalig) });
}
const ondAI = pc.posten.find(p => p.id === 'onderhoud_ai');
const ondWeb = pc.posten.find(p => p.id === 'onderhoud_website');
if (ondAI) {
  totalen.push({ label: 'Onderhoud AI per maand', bedrag: (ondAI.vanaf ? 'vanaf ' : '') + euro(ondAI.bedrag) });
}
if (ondWeb) {
  totalen.push({ label: 'Onderhoud website per maand', bedrag: '(optioneel) ' + (ondWeb.vanaf ? 'vanaf ' : '') + euro(ondWeb.bedrag) });
}

if (pc.posten.length === 0) {
  waarschuwingen.push('Er bleef geen enkele geldige post over. Deze aanvraag niet zomaar doorsturen!');
}
if (pc.geweigerd && pc.geweigerd.length > 0) {
  waarschuwingen.push('Geweigerde id\'s uit de aanvraag: ' + pc.geweigerd.join(', '));
}

// Vaste teksten
const aanhef = pc.naam ? 'Beste ' + pc.naam + ',' : 'Beste,';
const dank = pc.bedrijf ? 'Dank voor uw aanvraag voor ' + pc.bedrijf + '.' : 'Dank voor uw aanvraag.';
const vast1 = 'Dit is een vrijblijvende prijsindicatie, geen bindende offerte.';
const vast2 = 'De definitieve prijs hangt af van uw wensen en volgt na een gesprek. Alle prijzen zijn exclusief btw.';
const afs1 = 'Graag bespreek ik uw wensen verder in een kort gesprek (online) of via mail.';
const afs2 = 'U kunt hiervoor eenvoudig op deze e-mail antwoorden.';

const terInfoRegels = [
  'Klant: ' + (pc.naam || '-') + ' <' + (pc.email || '-') + '>',
  'Bedrijf: ' + (pc.bedrijf || '-') + ' | Telefoon: ' + (pc.telefoon || '-'),
  'Pad: ' + pc.pad,
  'Opmerking klant: ' + (pc.opmerking || '-'),
  'Samenvatting: ' + (samenvatting || '-'),
  'Waarschuwingen: ' + (waarschuwingen.length ? waarschuwingen.join(' | ') : 'geen')
];

// ---------- Tekstversie ----------
const toelTekst = onderdelen.length
  ? onderdelen.map(o => '- ' + o.onderdeel + ' – ' + o.zin + (o.vraag ? '\n  Vraag: ' + o.vraag : '')).join('\n')
  : ruweAI;
const klantmail = [
  aanhef,
  dank,
  'Dit is de prijsindicatie:',
  regels.map(r => '- ' + r.naam + ': ' + r.bedrag).join('\n'),
  totalen.map(t => t.label + ': ' + t.bedrag).join('\n'),
  vast1 + '\n' + vast2,
  toelTekst,
  antwoordOpmerking ? 'Antwoord op uw opmerking:\n' + antwoordOpmerking : '',
  afs1 + '\n' + afs2,
  'Met vriendelijke groeten,',
  'David',
  'weblotus – https://weblotus.be'
].filter(d => d && d.trim() !== '').join('\n\n');
const terInfo = ['TER INFO (niet doorsturen)'].concat(terInfoRegels).join('\n');
const conceptTekst = terInfo + '\n\n==============================\nMAIL AAN DE KLANT\nOnderwerp: Uw prijsindicatie van Weblotus\n==============================\n\n' + klantmail;

// ---------- HTML-versie ----------
const NAVY = '#0d2340', BAND = '#0d2340', TXT = '#1e2d3d', LIJN = '#dbe6f0', VRAAG = '#17426f', ROZE = '#fd34ad';
const td = 'padding:7px 0;border-bottom:1px solid ' + LIJN + ';';
const prijsRijen = regels.map(r =>
  '<tr><td style="' + td + '">' + esc(r.naam) + '</td><td style="' + td + 'text-align:right;white-space:nowrap;">' + esc(r.bedrag) + '</td></tr>'
).join('');
const totaalRijen = totalen.map((t, i) =>
  '<tr><td style="padding:' + (i === 0 ? '8px' : '2px') + ' 0 2px 0;"><strong>' + esc(t.label) + '</strong></td>' +
  '<td style="padding:' + (i === 0 ? '8px' : '2px') + ' 0 2px 0;text-align:right;white-space:nowrap;"><strong>' + esc(t.bedrag) + '</strong></td></tr>'
).join('');
const toelHtml = onderdelen.length
  ? onderdelen.map(o =>
      '<p style="margin:0 0 4px 0;"><strong>' + esc(o.onderdeel) + '</strong> – ' + esc(o.zin) + '</p>' +
      (o.vraag
        ? '<p style="margin:0 0 16px 18px;color:' + VRAAG + ';"><strong>Vraag:</strong> ' + esc(o.vraag) + '</p>'
        : '<div style="height:12px;line-height:12px;font-size:12px;">&nbsp;</div>')
    ).join('')
  : '<p style="margin:0 0 16px 0;white-space:pre-line;">' + esc(ruweAI) + '</p>';
const antwoordHtml = antwoordOpmerking
  ? '<p style="margin:0 0 4px 0;"><strong>Antwoord op uw opmerking:</strong></p>' +
    '<p style="margin:0 0 16px 0;">' + esc(antwoordOpmerking) + '</p>'
  : '';

const klantmailHtml =
  '<table width="100%" cellpadding="0" cellspacing="0" style="max-width:784px;margin:0 auto;background:#ffffff;border-collapse:collapse;font-family:Segoe UI,Arial,sans-serif;">' +
  '<tr><td style="padding:28px 100px;color:' + TXT + ';font-size:15px;line-height:1.6;">' +
  '<p style="margin:0 0 16px 0;">' + esc(aanhef) + '</p>' +
  '<p style="margin:0 0 20px 0;">' + esc(dank) + '</p>' +
  '<p style="margin:0 0 8px 0;font-size:16px;"><strong>Dit is de prijsindicatie:</strong></p>' +
  '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:15px;">' + prijsRijen + '</table>' +
  '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin-top:12px;border-top:2px solid ' + NAVY + ';font-size:15px;">' + totaalRijen + '</table>' +
  '<p style="margin:20px 0 24px 0;font-size:13px;color:#5a6b7d;">' + esc(vast1) + '<br>' + esc(vast2) + '</p>' +
  toelHtml +
  antwoordHtml +
  '<hr style="border:none;border-top:1px solid ' + LIJN + ';margin:8px 0 20px 0;">' +
  '<p style="margin:0 0 20px 0;">' + esc(afs1) + '<br>' + esc(afs2) + '</p>' +
  '<p style="margin:0 0 16px 0;">Met vriendelijke groeten,</p>' +
  '<p style="margin:0;"><strong>David</strong></p>' +
  '</td></tr>' +
  '<tr><td bgcolor="' + BAND + '" style="background:' + BAND + ';padding:16px 100px;">' +
  '<table cellpadding="0" cellspacing="0"><tr>' +
  '<td><img src="' + LOGO + '" width="56" height="56" alt="Weblotus" style="display:block;border:0;"></td>' +
  '<td style="padding-left:12px;color:#ffffff;font-size:20px;font-weight:600;letter-spacing:1px;font-family:Segoe UI,Arial,sans-serif;">weblotus</td>' +
  '<td style="padding-left:14px;font-size:14px;font-family:Segoe UI,Arial,sans-serif;"><a href="https://weblotus.be" style="color:' + ROZE + ';text-decoration:none;">https://weblotus.be</a></td>' +
  '</tr></table></td></tr></table>';

const terInfoHtml =
  '<table width="100%" cellpadding="0" cellspacing="0" style="max-width:784px;margin:0 auto 18px auto;border-collapse:collapse;">' +
  '<tr><td style="padding:14px;background:#f3f3f1;border:1px solid #d6d6d0;font-family:Consolas,monospace;font-size:13px;color:#444;line-height:1.5;">' +
  '<strong>TER INFO (niet doorsturen)</strong><br>' + terInfoRegels.map(esc).join('<br>') +
  '</td></tr></table>';

const conceptHtml =
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>' +
  '<body style="margin:0;padding:24px;background:#eef2f6;">' + terInfoHtml + klantmailHtml + '</body></html>';

// Mail aan de klant: zelfde opmaak, zonder TER INFO
const klantHtml =
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>' +
  '<body style="margin:0;padding:24px;background:#eef2f6;">' + klantmailHtml + '</body></html>';

return [{
  json: {
    onderwerp: 'Uw prijsindicatie van Weblotus',
    klantEmail: pc.email,
    naam: pc.naam,
    pad: pc.pad,
    samenvatting: samenvatting,
    antwoordOpmerking: antwoordOpmerking,
    totaalEenmalig: pc.totaalEenmalig,
    vanafEenmalig: pc.vanafEenmalig,
    totaalMaandelijks: pc.totaalMaandelijks,
    vanafMaandelijks: pc.vanafMaandelijks,
    waarschuwingen: waarschuwingen,
    klantmail: klantmail,
    terInfo: terInfo,
    conceptTekst: conceptTekst,
    conceptHtml: conceptHtml,
    klantHtml: klantHtml
  }
}];

// Beveiliging: controleert en kuist de aanvraag op, vóór er een prijs berekend wordt.
// weigeringen    -> aanvraag wordt niet verwerkt (Telegram "Geweigerd")
// waarschuwingen -> aanvraag gaat door, maar als concept naar info@weblotus.be

const origineel = $('Webhook').first().json.body || {};
const weigeringen = [];
const waarschuwingen = [];

// ---------- Velden opkuisen ----------
const tekst = v => String(v == null ? '' : v).trim();
const LINK = /(https?:\/\/|www\.|<[^>]*>)/i;

const naam = tekst(origineel.naam).slice(0, 60);
const bedrijf = tekst(origineel.bedrijf).slice(0, 60);
const email = tekst(origineel.email).toLowerCase();
const telefoon = tekst(origineel.telefoon).replace(/[^0-9+ ]/g, '').replace(/ {2,}/g, ' ').trim();
const opmerking = tekst(origineel.opmerking).slice(0, 1000);
const omschrijving = tekst(origineel.omschrijving_automatisering).slice(0, 1000);

if (!naam) weigeringen.push('Naam is leeg');
if (LINK.test(tekst(origineel.naam))) weigeringen.push('Link in naam');
if (LINK.test(tekst(origineel.bedrijf))) weigeringen.push('Link in bedrijf');
if (LINK.test(tekst(origineel.opmerking))) waarschuwingen.push('Link in opmerking');

// ---------- E-mailadres ----------
const emailGeldig = email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const domein = emailGeldig ? email.split('@').pop() : '';
if (!emailGeldig) weigeringen.push('Ongeldig e-mailadres');

// ---------- Turnstile ----------
const ts = $('Turnstile controle').first().json || {};
if (ts.error || typeof ts.success !== 'boolean') {
  waarschuwingen.push('Turnstile-controle niet bereikbaar');
} else if (ts.success !== true) {
  weigeringen.push('Turnstile mislukt (' + (ts['error-codes'] || []).join(', ') + ')');
}

// ---------- MX ----------
if (emailGeldig) {
  const mx = $('MX controle').first().json || {};
  const heeftMx = Array.isArray(mx.Answer) && mx.Answer.some(a => a.type === 15);
  if (mx.error || typeof mx.Status !== 'number') {
    waarschuwingen.push('MX-controle niet bereikbaar');
  } else if (mx.Status === 3) {
    weigeringen.push('Domein ' + domein + ' bestaat niet');
  } else if (mx.Status === 0 && !heeftMx) {
    weigeringen.push('Domein ' + domein + ' ontvangt geen mail (geen MX)');
  } else if (mx.Status !== 0) {
    waarschuwingen.push('MX-controle onduidelijk (Status ' + mx.Status + ')');
  }
}

// ---------- Geparkeerd domein (NS en MX) ----------
// Bron: MISP warninglist parking-domain-ns (versie 2022-10-24), zonder gewone hostingbedrijven, plus abovedomains.com
const PARKEER_NS = [
  'above.com', 'afternic.com', 'alter.com', 'bodis.com',
  'brainydns.com', 'brandbucket.com', 'chookdns.com', 'cnomy.com',
  'commonmx.com', 'dan.com', 'day.biz', 'dingodns.com',
  'dne.com', 'dnslink.com', 'dnsnuts.com', 'dnsspark.com',
  'domain-for-sale.at', 'domain-for-sale.se', 'domaincntrol.com', 'domainhasexpired.com',
  'domainist.com', 'domainmarket.com', 'domainmx.com', 'domainorderdns.nl',
  'domainparking.ru', 'domainrecover.com', 'dsredirection.com', 'dsredirects.com',
  'eftydns.com', 'emailverification.info', 'emu-dns.com', 'expiereddnsmanager.com',
  'expirationwarning.net', 'expired.uniregistry-dns.com', 'fabulous.com', 'failed-whois-verification.namecheap.com',
  'fastpark.net', 'hastydns.com', 'hostresolver.com', 'ibspark.com',
  'kirklanddc.com', 'koaladns.com', 'magpiedns.com', 'malkm.com',
  'milesmx.com', 'mytrafficmanagement.com', 'namedynamics.net', 'nameprovider.net',
  'ndsplitter.com', 'ns01.cashparking.com', 'ns02.cashparking.com', 'ns1.domain-is-4-sale-at-domainmarket.com',
  'ns1.domain.io', 'ns1.namefind.com', 'ns1.park.do', 'ns1.pql.net',
  'ns1.smartname.com', 'ns1.sonexo.eu', 'ns1.undeveloped.com', 'ns2.domain.io',
  'ns2.domainmarket.com', 'ns2.namefind.com', 'ns2.park.do', 'ns2.pql.net',
  'ns2.smartname.com', 'ns2.sonexo.com', 'ns2.undeveloped.com', 'ns3.tppns.com',
  'ns4.tppns.com', 'nsresolution.com', 'panamans.com', 'park1.encirca.net',
  'park2.encirca.net', 'parkdns1.internetvikings.com', 'parkdns2.internetvikings.com', 'parking-page.net',
  'parking.namecheap.com', 'parking1.ovh.net', 'parking2.ovh.net', 'parkingcrew.net',
  'parkingpage.namecheap.com', 'parkingspa.com', 'parklogic.com', 'parktons.com',
  'perfectdomain.com', 'quokkadns.com', 'redirectdom.com', 'redmonddc.com',
  'renewyourname.net', 'rentondc.com', 'rookdns.com', 'searchfusion.com',
  'searchreinvented.com', 'securetrafficrouting.com', 'sedo.com', 'sedoparking.com',
  'smtmdns.com', 'snparking.ru', 'squadhelp.com', 'sslparking.com',
  'tacomadc.com', 'taipandns.com', 'thednscloud.com', 'torresdns.com',
  'trafficcontrolrouter.com', 'trustednam.es', 'uniregistrymarket.link', 'verify-contact-details.namecheap.com',
  'voodoo.com', 'weaponizedcow.com', 'wombatdns.com', 'your-browser.this-domain.eu',
  'ztomy.com', 'abovedomains.com'
];
const PARKEER_MX = ['park-mx.above.com', 'parked.mail.mxtoolbox.com'];
const host = h => String(h || '').trim().toLowerCase().replace(/\.$/, '').split(' ').pop();
const past = (h, lijst) => lijst.some(p => h === p || h.endsWith('.' + p));
if (emailGeldig) {
  const ns = $('NS controle').first().json || {};
  const mxAntw = ($('MX controle').first().json || {}).Answer || [];
  if (ns.error || typeof ns.Status !== 'number') {
    waarschuwingen.push('NS-controle niet bereikbaar');
  } else {
    const nsHosts = (ns.Answer || []).filter(a => a.type === 2).map(a => host(a.data));
    const mxHosts = mxAntw.filter(a => a.type === 15).map(a => host(a.data));
    if (nsHosts.some(h => past(h, PARKEER_NS)) || mxHosts.some(h => past(h, PARKEER_MX))) {
      waarschuwingen.push('Geparkeerd domein (geen actief bedrijf): ' + domein);
    }
  }
}

// ---------- Wegwerplijst ----------
const lijst = $('Wegwerplijst').first().json || {};
if (lijst.error || typeof lijst.data !== 'string' || lijst.data.length < 1000) {
  waarschuwingen.push('Wegwerplijst niet geladen');
} else if (emailGeldig) {
  const wegwerp = new Set(
    lijst.data.split('\n').map(r => r.trim().toLowerCase()).filter(r => r && !r.startsWith('#'))
  );
  // ook subdomeinen: mail.wegwerp.com valt onder wegwerp.com
  const delen = domein.split('.');
  for (let i = 0; i < delen.length - 1; i++) {
    if (wegwerp.has(delen.slice(i).join('.'))) {
      waarschuwingen.push('Wegwerpadres (' + domein + ')');
      break;
    }
  }
}

// ---------- Aantal aanvragen vandaag ----------
const vandaag = $now.setZone('Europe/Brussels').toFormat('yyyy-LL-dd');
const rijenVandaag = $input.all()
  .map(i => i.json)
  .filter(r => String(r.datum || '').startsWith(vandaag));
const vanDitAdres = rijenVandaag.filter(r => String(r.email || '').trim().toLowerCase() === email).length;

if (emailGeldig && vanDitAdres >= 3) weigeringen.push('Al 3 aanvragen vandaag van ' + email);
if (rijenVandaag.length >= 50) weigeringen.push('Daglimiet van 50 aanvragen bereikt');

// ---------- Resultaat ----------
const body = Object.assign({}, origineel, {
  naam: naam,
  bedrijf: bedrijf,
  email: email,
  telefoon: telefoon,
  opmerking: opmerking,
  omschrijving_automatisering: omschrijving
});
delete body.turnstile;

return [{
  json: {
    toegelaten: weigeringen.length === 0,
    weigeringen: weigeringen,
    beveiligingWaarschuwingen: waarschuwingen,
    aanvragenVandaag: rijenVandaag.length,
    body: body
  }
}];
